.kb { padding: 24px; }
.kb-colunas { display: grid; gap: 16px; grid-template-columns: repeat(3, 1fr); align-items: start; }
@media (max-width: 720px) { .kb-colunas { grid-template-columns: 1fr; } }

.kb-coluna {
  border: 1px solid var(--border); border-radius: 12px; background: var(--bg-alt);
  padding: 14px;
  transition: border-color 0.15s ease;
}
.kb-coluna.kb-sobre { border-color: var(--accent); }

.kb-coluna header { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.kb-coluna h3 { margin: 0; font-family: 'Sora', sans-serif; font-size: 14px; }
/* Responde "onde está acumulando" sem contar card a card. */
.kb-conta {
  margin-left: auto; padding: 1px 9px; border-radius: 100px;
  background: var(--border-alt); font-size: 11px; color: var(--text-muted);
}

/* Coluna vazia precisa continuar sendo alvo: sem altura mínima não há onde soltar. */
.kb-lista { display: flex; flex-direction: column; gap: 8px; min-height: 60px; }

.kb-card {
  border: 1px solid var(--border); border-radius: 10px; background: var(--bg);
  padding: 12px; cursor: grab;
}
.kb-card.kb-movendo { opacity: 0.5; }
.kb-card h4 { margin: 0 0 4px; font-size: 13px; }
.kb-card p { margin: 0; font-size: 11px; color: var(--text-muted); }

.kb-mover { margin-top: 10px; display: none; width: 100%; }
.kb-mover select {
  width: 100%; padding: 7px 9px;
  border: 1px solid var(--border); border-radius: 7px;
  background: var(--bg-alt); color: var(--text); font: inherit; font-size: 12px;
}

/* A troca de interação. Mais preciso que largura é (pointer: coarse), que
   pergunta pelo apontador em vez do tamanho da janela — acerta o tablet com
   caneta e o desktop com tela sensível ao toque. */
@media (max-width: 720px) {
  .kb-card { cursor: default; }
  .kb-mover { display: block; }
}

.kb-dica { margin: 16px 0 0; font-size: 12px; color: var(--text-dim); }

