const COLUNAS = ['Novo', 'Em andamento', 'Concluído']

const CARDS = [
  { id: 'c1', titulo: 'Primeiro item', nota: 'Arraste ou use o seletor', coluna: 'Novo' },
  { id: 'c2', titulo: 'Segundo item', nota: 'A borda acende no alvo', coluna: 'Novo' },
  { id: 'c3', titulo: 'Terceiro item', nota: 'O contador acompanha', coluna: 'Em andamento' },
]

export function iniciarKanban(raiz, cards = CARDS) {
  /**
   * A transição de estado mora aqui, e só aqui. Arrastar e seletor são duas
   * interações para a MESMA regra — se cada uma tivesse a própria cópia,
   * qualquer mudança teria de ser feita duas vezes, e seria feita uma.
   */
  function mover(id, destino) {
    const card = cards.find((c) => c.id === id)
    if (!card || card.coluna === destino) return
    card.coluna = destino
    // Num sistema real, a tela muda aqui e a gravação vai depois: o card sai
    // da coluna quando a pessoa soltou, não quando a rede respondeu.
    render()
  }

  function render() {
    raiz.querySelectorAll('.kb-coluna').forEach((col) => {
      const nome = col.dataset.coluna
      const lista = col.querySelector('.kb-lista')
      const meus = cards.filter((c) => c.coluna === nome)
      col.querySelector('.kb-conta').textContent = String(meus.length)

      lista.innerHTML = meus
        .map(
          (c) => `<article class="kb-card" draggable="true" data-id="${c.id}">
            <h4>${c.titulo}</h4>
            <p>${c.nota}</p>
            <label class="kb-mover">
              <select aria-label="Mover ${c.titulo} para">
                ${COLUNAS.map((o) => `<option${o === c.coluna ? ' selected' : ''}>${o}</option>`).join('')}
              </select>
            </label>
          </article>`,
        )
        .join('')
    })
    ligar()
  }

  function ligar() {
    raiz.querySelectorAll('.kb-card').forEach((card) => {
      card.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', card.dataset.id)
        card.classList.add('kb-movendo')
      })
      card.addEventListener('dragend', () => card.classList.remove('kb-movendo'))

      // O outro caminho para a mesma função.
      card.querySelector('select').addEventListener('change', (e) => {
        mover(card.dataset.id, e.target.value)
      })
    })
  }

  raiz.querySelectorAll('.kb-coluna').forEach((col) => {
    // Sem o preventDefault no dragover o navegador recusa a soltura: o padrão
    // de todo elemento é não aceitar o que está sendo arrastado.
    col.addEventListener('dragover', (e) => {
      e.preventDefault()
      col.classList.add('kb-sobre')
    })
    col.addEventListener('dragleave', () => col.classList.remove('kb-sobre'))
    col.addEventListener('drop', (e) => {
      e.preventDefault()
      col.classList.remove('kb-sobre')
      mover(e.dataTransfer.getData('text/plain'), col.dataset.coluna)
    })
  })

  render()
}
